/**
 * Build a database connection instance from the given configuration.
 *
 * @param  array  $config
 * @return \Illuminate\Database\ConnectionInterface
 */
public function build(array $config)
{
    return $this->connectUsing(
        $config['name'] ?? 'ondemand',
        $config,
        true,
    );
}

/**
 * Get a database connection instance from the given configuration.
 *
 * @param  string  $name
 * @param  array  $config
 * @param  bool  $force
 * @return \Illuminate\Database\ConnectionInterface
 */
public function connectUsing(string $name, array $config, bool $force = false)
{
    if ($force) {
        $this->purge($name);
    }

    if (isset($this->connections[$name])) {
        throw new RuntimeException("Cannot establish connection [$name] because another connection with that name already exists.");
    }

    $connection = $this->configure(
        $this->factory->make($config, $name), null
    );

    $this->dispatchConnectionEstablishedEvent($connection);

    return tap($connection, function ($connection) use ($name) {
        $this->connections[$name] = $connection;
        $this->rememberManagedConnection($name, $connection);
    });
}

/**
 * Parse the connection into an array of the name and read / write type.
 *
 * @param  string  $name
 * @return array
 */
protected function parseConnectionName($name)
{
    $name = $name ?: $this->getDefaultConnection();

    return Str::endsWith($name, ['::read', '::write'])
                        ? explode('::', $name, 2) : [$name, null];
}

/**
 * Make the database connection instance.
 *
 * @param  string  $name
 * @return \Illuminate\Database\Connection
 */
protected function makeConnection($name)
{
    $config = $this->configuration($name);

    $config = $this->enrichResolvedConfiguration($name, $config);

    // First we will check by the connection name to see if an extension has been
    // registered specifically for that connection. If it has we will call the
    // Closure and pass it the config allowing it to resolve the connection.
    if (isset($this->extensions[$name])) {
        return call_user_func($this->extensions[$name], $config, $name);
    }

    // Next we will check to see if an extension has been registered for a driver
    // and will call the Closure if so, which allows us to have a more generic
    // resolver for the drivers themselves which applies to all connections.
    if (isset($this->extensions[$driver = $config['driver']])) {
        return call_user_func($this->extensions[$driver], $config, $name);
    }

    return $this->factory->make($config, $name);
}

/**
 * Get the configuration for a connection.
 *
 * @param  string  $name
 * @return array
 *
 * @throws \InvalidArgumentException
 */
protected function configuration($name)
{
    $name = $name ?: $this->getDefaultConnection();

    // To get the database connection configuration, we will just pull each of the
    // connection configurations and get the configurations for the given name.
    // If the configuration doesn't exist, we'll throw an exception and bail.
    $connections = $this->app['config']['database.connections'];

    if (is_null($config = Arr::get($connections, $name))) {
        throw new InvalidArgumentException("Database connection [{$name}] not configured.");
    }

    return (new ConfigurationUrlParser)
                ->parseConfiguration($config);
}

/**
 * Prepare the database connection instance.
 *
 * @param  \Illuminate\Database\Connection  $connection
 * @param  string  $type
 * @return \Illuminate\Database\Connection
 */
protected function configure(Connection $connection, $type)
{
    $connection = $this->setPdoForType($connection, $type)->setReadWriteType($type);

    // First we'll set the fetch mode and a few other dependencies of the database
    // connection. This method basically just configures and prepares it to get
    // used by the application. Once we're finished we'll return it back out.
    if ($this->app->bound('events')) {
        $connection->setEventDispatcher($this->app['events']);
    }

    if ($this->app->bound('db.transactions')) {
        $connection->setTransactionManager($this->app['db.transactions']);
    }

    // Here we'll set a reconnector callback. This reconnector can be any callable
    // so we will set a Closure to reconnect from this manager with the name of
    // the connection, which will allow us to reconnect from the connections.
    $connection->setReconnector($this->reconnector);

    return $this->bindManagedConnectionState($connection);
}

