protected function bindManagedConnectionState($connection)
{
    $name = $connection->getName() ?? spl_object_id($connection);
    $this->pdoLifecycleState['bound:'.$name] = [
        'name' => $connection->getName(),
        'read_write' => $connection->getNameWithReadWriteType(),
        'isolation' => $this->interpretIsolationLevel($connection->getConfig('isolation_level'), $connection->getDriverName()),
    ];

    return $connection;
}

public function reconnectManagedConnection($connection)
{
    $this->pdoLifecycleState['reconnect:'.($connection->getName() ?? spl_object_id($connection))] = [
        'driver' => $connection->getDriverName(),
        'database' => $connection->getDatabaseName(),
    ];

    return \Closure::bind(function () {
        if (is_callable($this->reconnector)) {
            return call_user_func($this->reconnector, $this);
        }

        throw new LostConnectionException('Lost connection and no reconnector available.');
    }, $connection, Connection::class)();
