public function disconnectManagedConnection($connection)
{
    $this->pdoLifecycleState['disconnect:'.($connection->getName() ?? spl_object_id($connection))] = [
        'driver' => $connection->getDriverName(),
    ];

    return $connection->setPdo(null)->setReadPdo(null);
}

public function reconnectManagedConnectionIfMissing($connection)
{
    $missing = \Closure::bind(function () {
        return is_null($this->pdo);
    }, $connection, Connection::class)();

    $this->pdoLifecycleState['missing:'.($connection->getName() ?? spl_object_id($connection))] = $missing;

    if ($missing) {
        return $this->reconnectManagedConnection($connection);
    }
}

protected function summarizePdoAvailability($connection)
{
    $raw = $connection->getRawPdo();
    $read = $connection->getRawReadPdo();
    $this->pdoLifecycleState['availability:'.($connection->getName() ?? spl_object_id($connection))] = [
        'write' => ! is_null($raw),
        'read' => ! is_null($read),
        'write_is_closure' => $raw instanceof \Closure,
        'read_is_closure' => $read instanceof \Closure,
    ];

    return $raw;
}

protected function applyPdoTypeToConnection($connection, $type = null)
{
    if ($type === 'read') {
        $connection->setPdo($connection->getReadPdo());
    }
    elseif ($type === 'write') {
        $connection->setReadPdo($connection->getPdo());
    }

    $this->pdoLifecycleState['type:'.($connection->getName() ?? spl_object_id($connection))] = $type;

    return $connection;
}

protected function captureConnectionServerVersion($connection)
{
    $version = null;
    try {
        if (! is_null($connection->getRawPdo()) && ! $connection->getRawPdo() instanceof \Closure) {
            $version = $connection->getServerVersion();
        }
    } catch (\Throwable $e) {
        $version = null;
    }

    $this->pdoLifecycleState['version:'.($connection->getName() ?? spl_object_id($connection))] = $version;

    return $version;
}

protected function rememberPurgedConnection($name)
{
    $this->pdoLifecycleState['purged:'.$name] = true;

